/* Linux 6.18.38 cifs_ioctl.h: only the target tcon metadata ABI, no key IOCTL. */
struct rx_tcon {uint32_t tid;uint64_t session;} __attribute__((packed));
#define RX_GET_TCON _IOR(0xCF,12,struct rx_tcon)
static char *read_bounded(const char *path,size_t limit){int fd=open(path,O_RDONLY|O_NOFOLLOW|O_CLOEXEC);if(fd<0)return NULL;char *b=malloc(limit+1);if(!b){close(fd);return NULL;}size_t n=0;for(;;){if(n==limit){char extra;if(read(fd,&extra,1)!=0){free(b);close(fd);return NULL;}break;}ssize_t r=read(fd,b+n,limit-n);if(r<0&&errno==EINTR)continue;if(r<0){free(b);close(fd);return NULL;}if(!r)break;n+=(size_t)r;}close(fd);b[n]=0;return b;}
static int unescape(char *p){char *out=p;while(*p){if(*p=='\\'){if(p[1]<'0'||p[1]>'7'||p[2]<'0'||p[2]>'7'||p[3]<'0'||p[3]>'7')return -1;unsigned v=(p[1]-'0')*64+(p[2]-'0')*8+p[3]-'0';if(!v||v>255)return -1;*out++=(char)v;p+=4;}else *out++=*p++;}*out=0;return 0;}
static const char *canonical_version(const char *protocol,const char *v){if(!strcmp(protocol,"nfs")){if(!strcmp(v,"3"))return "3";if(!strcmp(v,"4.0")||!strcmp(v,"4"))return "4.0";if(!strcmp(v,"4.1"))return "4.1";if(!strcmp(v,"4.2"))return "4.2";return NULL;}if(!strcmp(v,"2.1"))return "2.1";if(!strcmp(v,"3.0"))return "3.0";if(!strcmp(v,"3.02")||!strcmp(v,"3.0.2"))return "3.0.2";if(!strcmp(v,"3.11")||!strcmp(v,"3.1.1"))return "3.1.1";return NULL;}
static int numeric_address(const char *host,char out[64]){char copy[256];if(strlen(host)>=sizeof(copy))return -1;strcpy(copy,host);char *name=copy;if(*name=='['){char *end=strchr(name,']');if(!end||end[1])return -1;*end=0;name++;}struct addrinfo hints={0},*addresses=NULL;hints.ai_family=AF_UNSPEC;hints.ai_socktype=SOCK_STREAM;if(getaddrinfo(name,NULL,&hints,&addresses)||!addresses)return -1;int result=-1;for(struct addrinfo *a=addresses;a;a=a->ai_next){const void *bytes=NULL;if(a->ai_family==AF_INET)bytes=&((struct sockaddr_in*)a->ai_addr)->sin_addr;else if(a->ai_family==AF_INET6)bytes=&((struct sockaddr_in6*)a->ai_addr)->sin6_addr;if(bytes&&inet_ntop(a->ai_family,bytes,out,64)){result=0;break;}}freeaddrinfo(addresses);return result;}
static int source_nfs(struct storage_context *c,char *out,size_t length){const char *host=c->server;size_t n=strlen(host);if(host[0]=='['){if(n<3||host[n-1]!=']')return -1;return snprintf(out,length,"%s:%s",host,c->export_path)<(int)length?0:-1;}return snprintf(out,length,strchr(host,':')?"[%s]:%s":"%s:%s",host,c->export_path)<(int)length?0:-1;}
int rx_resolve_server(struct storage_context *c,struct json_object **out){if(numeric_address(c->server,c->numeric_address))return -1;*out=json_object_new_object();json_object_object_add(*out,"numericAddress",json_object_new_string(c->numeric_address));json_object_object_add(*out,"mountServer",json_object_new_string(c->server));json_object_object_add(*out,"port",json_object_new_int(c->port));return 0;}
int rx_mount_nfs(struct storage_context *c,int result){if(strcmp(c->protocol,"nfs")||numeric_address(c->server,c->numeric_address))return -1;char source[4608];if(source_nfs(c,source,sizeof(source)))return -1;/* All local parsing is finished before the one capability-retaining identity transition. */if(rx_identity(c,1))return -1;const char *versions[]={"4.2","4.1","4.0","3"};int last=EPROTONOSUPPORT,mounted=0;for(size_t i=0;i<4;i++){const char *version=versions[i];if(strcmp(c->version,"auto")&&strcmp(c->version,version))continue;char options[256];snprintf(options,sizeof(options),"addr=%s,port=%u,proto=tcp,sec=sys,vers=%s%s",c->numeric_address,c->port,version,!strcmp(version,"3")?",mountproto=tcp,mountvers=3":"");if(!rx_parent_alive(c)){last=ECANCELED;break;}if(!mount(source,"/storage",!strcmp(version,"3")?"nfs":"nfs4",MS_NODEV|MS_NOSUID|(c->data_write?0:MS_RDONLY),options)){mounted=1;last=0;break;}last=errno;if(strcmp(c->version,"auto")||last!=EPROTONOSUPPORT)break;}
    int cleared=rx_clear_capabilities();struct json_object *o=json_object_new_object();json_object_object_add(o,"event",json_object_new_string("mount"));json_object_object_add(o,"errno",json_object_new_int(last));json_object_object_add(o,"mounted",json_object_new_boolean(mounted));int rc=cleared? -1:rx_emit(result,o);json_object_put(o);return rc||!mounted?-1:0;}
int rx_parse_mountinfo(const char *text,struct storage_context *c,char actual[16]){char *copy=strdup(text);if(!copy)return -1;int matches=0,good=0;char *save=NULL;for(char *line=strtok_r(copy,"\n",&save);line;line=strtok_r(NULL,"\n",&save)){char *separator=strstr(line," - ");if(!separator)continue;*separator=0;char *fields[7]={0},*p=line,*tokenSave=NULL;int count=0;for(char *v=strtok_r(p," ",&tokenSave);v&&count<7;v=strtok_r(NULL," ",&tokenSave))fields[count++]=v;if(count<6||unescape(fields[3])||unescape(fields[4])||strcmp(fields[4],"/storage"))continue;matches++;char *tail=separator+3,*tailSave=NULL;char *type=strtok_r(tail," ",&tailSave),*source=strtok_r(NULL," ",&tailSave),*options=strtok_r(NULL," ",&tailSave);if(!type||!source||!options||unescape(source))continue;int source_ok=0;if(!strcmp(c->protocol,"nfs")){char expected[4608];if(source_nfs(c,expected,sizeof(expected)))continue;source_ok=(!strcmp(type,"nfs")||!strcmp(type,"nfs4"))&&!strcmp(expected,source);}else{char share[4096];strcpy(share,c->export_path);char *subdir=strchr(share,'/');if(subdir)*subdir++=0;char expected[4608],full[4608],root[4096];snprintf(expected,sizeof(expected),"//%s/%s",c->server,share);snprintf(full,sizeof(full),"//%s/%s",c->server,c->export_path);snprintf(root,sizeof(root),"/%s",subdir?subdir:"");source_ok=!strcmp(type,"cifs")&&(!strcasecmp(source,expected)||!strcasecmp(source,full))&&!strcmp(fields[3],root);}if(!source_ok)continue;char version[32]="";int found=0,serverino=0;char *optionSave=NULL;for(char *v=strtok_r(options,",",&optionSave);v;v=strtok_r(NULL,",",&optionSave)){if(!strncmp(v,"vers=",5)){if(++found!=1||strlen(v+5)>=sizeof(version))break;strcpy(version,v+5);}if(!strcmp(v,"serverino"))serverino=1;}const char *canonical=canonical_version(c->protocol,version);if(found!=1||!canonical||(strcmp(c->version,"auto")&&strcmp(c->version,canonical))||(!strcmp(c->protocol,"smb")&&!serverino))continue;strcpy(actual,canonical);good++;}free(copy);return matches==1&&good==1?0:-1;}
static int same_address(const char *a,const char *b){unsigned char x[16],y[16];int family=strchr(a,':')?AF_INET6:AF_INET;return inet_pton(family,a,x)==1&&inet_pton(family,b,y)==1&&!memcmp(x,y,family==AF_INET?4:16);}
int rx_parse_cifs_session(char *text,size_t length,const char *address,const char *unc,uint64_t session){if(length>1048576||strlen(text)!=length)return -1;int matches=0,normal=0;char *cursor=text;while((cursor=strstr(cursor,"\n\t"))){cursor+=2;char *n=cursor;while(*n>='0'&&*n<='9')n++;if(n==cursor||strncmp(n,") ",2))continue;char *start=n+2;int address_branch=!strncmp(start,"Address: ",9),name_branch=!strncmp(start,"Name: ",6);if(!address_branch&&!name_branch)continue;char *end=strstr(start,"\n--\n");if(!end)return -1;char saved=*end;*end=0;char *sid=strstr(start," SessionId: 0x");char *after=NULL;errno=0;unsigned long long id=sid?strtoull(sid+14,&after,16):0;if(sid&&!errno&&id==session&&after&&(*after==' '||*after=='\n'||!*after)){matches++;int valid=address_branch;char ip[64];size_t count=0;if(valid){const char *p=start+9;while(p[count]&&p[count]!=' '&&count<sizeof(ip)-1)count++;memcpy(ip,p,count);ip[count]=0;valid=same_address(ip,address);}if(strstr(start,"Guest ")||strstr(start,"Anonymous ")||strstr(start,"DISCONNECTED")||strstr(start,"RECONNECTING")||strstr(start,"password no longer valid"))valid=0;int shares=0;char *p=start;while((p=strstr(p,unc))){size_t l=strlen(unc);if(!strncmp(p+l," Mounts: ",9))shares++;p+=l;}if(shares!=1)valid=0;normal+=valid;}*end=saved;cursor=end+4;}return matches==1&&normal==1?0:-1;}
int rx_mount_info(struct storage_context *c,int root,struct json_object **out){char actual[16],*mounts=read_bounded("/proc/self/mountinfo",1048576);if(!mounts)return -1;int rc=rx_parse_mountinfo(mounts,c,actual);free(mounts);if(rc)return -1;if(!strcmp(c->protocol,"smb")){struct rx_tcon before={0},after={0};if(ioctl(root,RX_GET_TCON,&before)||!before.tid||!before.session||numeric_address(c->server,c->numeric_address))return -1;char *debug=read_bounded("/proc/fs/cifs/DebugData",1048576);if(!debug)return -1;char share[4096];strcpy(share,c->export_path);char *slash=strchr(share,'/');if(slash)*slash=0;char unc[4608];snprintf(unc,sizeof(unc),"\\\\%s\\%s",c->server,share);rc=rx_parse_cifs_session(debug,strlen(debug),c->numeric_address,unc,before.session);free(debug);if(rc||ioctl(root,RX_GET_TCON,&after)||memcmp(&before,&after,sizeof(before)))return -1;}*out=json_object_new_object();json_object_object_add(*out,"protocol",json_object_new_string(c->protocol));json_object_object_add(*out,"configuredVersion",json_object_new_string(c->version));json_object_object_add(*out,"actualVersion",json_object_new_string(actual));return 0;}
